<?php
require_once __DIR__ . '/../../includes/db.php';require_once __DIR__ . '/../includes/auth.php';require_login();
if(!isset($_GET['id'])||!is_numeric($_GET['id'])){set_flash('error','Car ID missing.');redirect_to('backend/cars/list.php');}$car_id=(int)$_GET['id'];
$stmt=$conn->prepare('SELECT * FROM cars WHERE id=?');$stmt->bind_param('i',$car_id);$stmt->execute();$car=$stmt->get_result()->fetch_assoc();if(!$car){set_flash('error','Car not found.');redirect_to('backend/cars/list.php');}
$stmt=$conn->prepare('SELECT IFNULL(SUM(amount),0) total_cost FROM car_costs WHERE car_id=?');$stmt->bind_param('i',$car_id);$stmt->execute();$costs=$stmt->get_result()->fetch_assoc();
$stmt=$conn->prepare('SELECT cs.*,d.name dalali_name,IFNULL(p.paid,0) paid FROM car_sales cs LEFT JOIN dalalis d ON d.id=cs.dalali_id LEFT JOIN(SELECT sale_id,SUM(amount) paid FROM sale_payments GROUP BY sale_id)p ON p.sale_id=cs.id WHERE cs.car_id=? LIMIT 1');$stmt->bind_param('i',$car_id);$stmt->execute();$sale=$stmt->get_result()->fetch_assoc();$profit=$sale?(float)$sale['sale_price']-((float)$car['purchase_price']+(float)$costs['total_cost']):null;
$stmt=$conn->prepare("SELECT * FROM reservations WHERE car_id=? ORDER BY status='ACTIVE' DESC,created_at DESC LIMIT 5");$stmt->bind_param('i',$car_id);$stmt->execute();$reservations=$stmt->get_result();
$stmt=$conn->prepare('SELECT * FROM car_documents WHERE car_id=? ORDER BY created_at DESC');$stmt->bind_param('i',$car_id);$stmt->execute();$documents=$stmt->get_result();
$stmt=$conn->prepare('SELECT * FROM test_drives WHERE car_id=? ORDER BY test_date DESC LIMIT 5');$stmt->bind_param('i',$car_id);$stmt->execute();$tests=$stmt->get_result();
$page_title='Car Details';include __DIR__.'/../includes/header.php';include __DIR__.'/../includes/leftsidebar.php';
?>
