<div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(280px,1fr));"><div class="card"><h2>Vehicle Information</h2><p><strong>Name:</strong> <?=e($car['car_name'])?></p><p><strong>Make / Model:</strong> <?=e(trim(($car['make']??'').' '.($car['model']??''))?:'—')?></p><p><strong>Year / Color:</strong> <?=e(($car['model_year']?:'—').' / '.($car['color']?:'—'))?></p><p><strong>Plate Number:</strong> <?=e(car_sales_plate_label($car['plate_number']))?></p><p><strong>Chassis Number:</strong> <?=e($car['chassis_number'])?></p><p><strong>Engine Number:</strong> <?=e($car['engine_number']?:'—')?></p><p><strong>Mileage:</strong> <?=$car['mileage']?number_format((float)$car['mileage']).' km':'—'?></p><p><strong>Transmission / Fuel:</strong> <?=e(($car['transmission']?:'—').' / '.($car['fuel_type']?:'—'))?></p><p><strong>Status:</strong> <span class="badge <?= $car['status']==='SOLD'?'sold':'stock' ?>"><?=e($car['status'])?></span></p></div>
<div class="card"><h2>Financial Overview</h2><p><strong>Purchase Price:</strong> <?=money($car['purchase_price'])?></p><p><strong>Asking Price:</strong> <?=$car['asking_price']?money($car['asking_price']):'—'?></p><p><strong>Total Costs:</strong> <?=money($costs['total_cost'])?></p><p><strong>Total Investment:</strong> <?=money($car['purchase_price']+$costs['total_cost'])?></p><p><strong>Sale Price:</strong> <?= $sale?money($sale['sale_price']):'Not sold' ?></p><?php if($sale):?><p><strong>Amount Paid:</strong> <?=money($sale['paid'])?></p><p><strong>Balance:</strong> <?=money(max(0,$sale['sale_price']-$sale['paid']))?></p><?php endif;?><p><strong>Profit/Loss:</strong> <?php if($profit!==null):?><span class="<?= $profit>=0?'profit-positive':'profit-negative' ?>"><?=money($profit)?></span><?php else: ?>—<?php endif;?></p></div>
<div class="card"><h2>Stock Source</h2><p><strong>Type:</strong> <?=e($car['stock_type']??'OWNED')?></p><p><strong>Supplier:</strong> <?=e($car['supplier_name']?:'—')?></p><p><strong>Supplier Phone:</strong> <?=e($car['supplier_phone']?:'—')?></p><p><strong>Owner:</strong> <?=e($car['owner_name']?:'—')?></p><p><strong>Owner Phone:</strong> <?=e($car['owner_phone']?:'—')?></p><p><strong>Yard / Branch:</strong> <?=e($car['yard_location']?:'—')?></p><p><strong>Notes:</strong> <?=e($car['vehicle_notes']?:'—')?></p></div>
<?php if($sale):?><div class="card"><h2>Sale Information</h2><p><strong>Buyer:</strong> <?=e($sale['buyer_name'])?></p><p><strong>Phone:</strong> <?=e($sale['buyer_phone'] ?? '—')?></p><p><strong>Email:</strong> <?=e($sale['buyer_email'] ?? '—')?></p><p><strong>Sale Date:</strong> <?=e($sale['sale_date'])?></p><p><strong>Payment:</strong> <?=e($sale['payment_status'])?></p><p><strong>Dalali:</strong> <?=e($sale['dalali_name']?:'Direct sale')?></p><p><strong>Notes:</strong> <?=e($sale['notes'] ?? '—')?></p></div><?php endif;?></div>
<div class="card"><div class="report-title"><h2>Reservations</h2><a class="btn" href="../reservations/index.php">All Reservations</a></div><div class="table-responsive"><table class="table"><thead><tr><th>Customer</th><th>Deposit</th><th>Date</th><th>Expiry</th><th>Status</th></tr></thead><tbody><?php while($r=$reservations->fetch_assoc()):?><tr><td><?=e($r['customer_name'])?></td><td><?=money($r['deposit_amount'])?></td><td><?=e($r['reserve_date'])?></td><td><?=e($r['expiry_date']?:'—')?></td><td><?=e($r['status'])?></td></tr><?php endwhile;?></tbody></table></div></div>
<div class="card"><div class="report-title"><h2>Vehicle Documents</h2><a class="btn" href="../documents/index.php?car_id=<?=$car_id?>">All Documents</a></div><div class="table-responsive"><table class="table"><thead><tr><th>Document</th><th>Number</th><th>Status</th><th>Expiry</th></tr></thead><tbody><?php while($d=$documents->fetch_assoc()):?><tr><td><?=e($d['document_type'])?></td><td><?=e($d['document_number']?:'—')?></td><td><?=e($d['status'])?></td><td><?=e($d['expiry_date']?:'—')?></td></tr><?php endwhile;?></tbody></table></div></div>
<div class="card"><div class="report-title"><h2>Recent Test Drives</h2><a class="btn" href="../testdrives/index.php">All Test Drives</a></div><div class="table-responsive"><table class="table"><thead><tr><th>Date</th><th>Customer</th><th>Phone</th><th>Outcome</th></tr></thead><tbody><?php while($t=$tests->fetch_assoc()):?><tr><td><?=e($t['test_date'])?></td><td><?=e($t['customer_name'])?></td><td><?=e($t['customer_phone']?:'—')?></td><td><?=e($t['outcome'])?></td></tr><?php endwhile;?></tbody></table></div></div></div><?php include __DIR__.'/../includes/footer.php'; ?>
